#!/usr/bin/env node
// One authority per vocabulary: the allow-lists packages/core refuses by are the schemas' own values, imported from
// packages/core/src/standard/schema-vocab.ts (generated by packages/schema/generate.mjs, `npm run schema:generate`),
// never a second hand-typed copy. Asserts, one line each:
//   stale     the vocab module is one of generate.mjs's outputs: handed it missing, the stale loop --check runs reports
//             `FAIL  packages/core/src/standard/schema-vocab.ts is missing`
//   identity  waves.ts's WAVE_MODELS / WAVE_EFFORTS / MAX_NAME / MAX_PACKAGES, jobs.ts's SAFE_ID and manifest-check.ts's
//             BUILTIN_IDS / TOP are the generated values (=== where they are the same object), equal to the schema's
//   seeded    scan-wire-1's waveEffort gaining 'max' in memory: emitVocab carries it, and checkWaveBody loaded over that
//             generated module (a temp copy of waves.ts + jobs.ts, no core edit) accepts effort 'max'
//   scope     scan-sim.ts and scans/route.ts take their scope kinds from the generated SCAN_SCOPE_KINDS
//   literals  no array or Set literal of >= 3 strings in packages/core/src (comments stripped, schema-vocab.ts excluded)
//             has the member set of a schema string enum; a seeded control text is reported, naming the enum
//   scrapers  generate.mjs reads no constant out of source text (constOf, reOf, BUILTIN_SET_RE are gone)
//   GUARD     SAFE_ID's behaviour is unchanged: 'k-des-3' and 'K-DES-3' pass, '-x' and an 82-character id do not
// Run: node scripts/check-schema-vocab.mjs   (Node type stripping; exit 1 on any failure)
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { stripComments } from './lib/source.ts';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const VOCAB = 'packages/core/src/standard/schema-vocab.ts';
const rel = (p) => path.relative(ROOT, p).split(path.sep).join('/');
const read = (r) => fs.readFileSync(path.join(ROOT, r), 'utf8');
const load = async (r) => { try { return await import(pathToFileURL(path.join(ROOT, r)).href); } catch (e) { return { __error: e.message.split('\n')[0] }; } };
const schemaOf = (f) => JSON.parse(read(`packages/schema/schema/${f}`));
const wire = schemaOf('scan-wire-1.schema.json'), lens = schemaOf('lens-manifest-1.schema.json');
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

let failed = 0, passed = 0;
const check = (name, ok, detail = '') => {
  if (ok) passed++; else failed++;
  console.log(`${ok ? 'ok  ' : 'FAIL'}  ${name}${ok || !detail ? '' : `  (${detail})`}`);
};

const G = await load('packages/schema/generate.mjs');
const V = await load(VOCAB);
const W = await load('packages/core/src/scan/waves.ts');
const J = await load('packages/core/src/scan/jobs.ts');
const M = await load('packages/core/src/scan/manifest-check.ts');

// 1. stale: the vocab module joins the stale loop
{
  let got = [], why = '';
  if (typeof G.staleReport !== 'function' || typeof G.outputsOf !== 'function') why = 'generate.mjs exports no staleReport / outputsOf';
  else {
    const fresh = G.generate(G.readSchemas()), outputs = G.outputsOf(fresh);
    const texts = new Map(outputs);
    got = G.staleReport(outputs, (f) => (rel(f) === VOCAB ? null : texts.get(f)), 'probe').map((r) => r.line);
    why = got.join(' / ');
  }
  const want = `FAIL  ${VOCAB} is missing: run npm run schema:generate`;
  check(`stale: ${VOCAB} handed as missing is reported by generate.mjs's stale loop ("${want.slice(0, 60)}..."), the other outputs current`,
    got.includes(want) && got.filter((l) => l.startsWith('ok    ')).length === got.length - 1, why);
}

// 2. identity: waves.ts's allow-lists and bounds are the generated bindings, and the schema's values
{
  const d = wire.$defs;
  const rows = [
    ['WAVE_MODELS', W.WAVE_MODELS, V.WAVE_MODELS, d.waveModel.enum],
    ['WAVE_EFFORTS', W.WAVE_EFFORTS, V.WAVE_EFFORTS, d.waveEffort.enum],
    ['MAX_NAME', W.MAX_NAME, V.WAVE_NAME_MAX_LENGTH, d.waveName.maxLength],
    ['MAX_PACKAGES', W.MAX_PACKAGES, V.WAVE_PACKAGES_MAX_ITEMS, d.wave.properties.packages.maxItems],
  ];
  const bad = rows.filter(([, w, v, s]) => w === undefined || w !== v || !same(v, s)).map(([n, w, v, s]) => `${n}: waves.ts ${JSON.stringify(w)}, vocab ${JSON.stringify(v)}, schema ${JSON.stringify(s)}`);
  check('identity: waves.ts WAVE_MODELS, WAVE_EFFORTS, MAX_NAME, MAX_PACKAGES are the generated bindings (===) and scan-wire-1\'s values', !V.__error && !W.__error && !bad.length, V.__error ?? W.__error ?? bad.join('; '));
}

// 3. seeded: a value added to waveEffort reaches checkWaveBody through generation alone
{
  let why = '', ok = false;
  if (typeof G.emitVocab !== 'function') why = 'generate.mjs exports no emitVocab';
  else {
    const schemas = G.readSchemas(), seeded = structuredClone(schemas);
    seeded['scan-wire-1.schema.json'].$defs.waveEffort.enum.push('max');
    const text = G.emitVocab(G.model(seeded));
    const line = text.split('\n').find((l) => /\bWAVE_EFFORTS\b/.test(l) && l.includes('export const')) ?? '';
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'bp-schema-vocab-'));
    try {
      const core = path.join(tmp, 'packages/core/src');
      fs.mkdirSync(path.join(core, 'scan'), { recursive: true }); fs.mkdirSync(path.join(core, 'standard'), { recursive: true });
      fs.writeFileSync(path.join(tmp, 'package.json'), '{ "type": "module" }\n');
      for (const f of ['scan/waves.ts', 'scan/jobs.ts']) fs.copyFileSync(path.join(ROOT, 'packages/core/src', f), path.join(core, f));
      fs.writeFileSync(path.join(core, 'standard/schema-vocab.ts'), text);
      const SW = await import(pathToFileURL(path.join(core, 'scan/waves.ts')).href);
      const body = { name: 'w', packages: [{ name: 'p', model: 'opus', effort: 'max', ids: ['k-des-3'] }] };
      const r = SW.checkWaveBody(body), real = W.checkWaveBody?.(body);
      ok = line.includes("'max'") && r?.ok === true && real?.ok === false;
      why = `vocab line "${line.trim()}", seeded checkWaveBody ${JSON.stringify(r)}, real ${JSON.stringify(real)}`;
    } catch (e) { why = e.message.split('\n')[0]; } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
  }
  check("seeded: waveEffort gaining 'max' in memory -> emitVocab's WAVE_EFFORTS carries it and checkWaveBody over that module accepts effort 'max' (the real one refuses it)", ok, why);
}

// 4. scope: both scope-kind allow-lists are the generated SCAN_SCOPE_KINDS
{
  const files = ['packages/core/src/model/scan-sim.ts', 'packages/core/src/server/api/products/[slug]/scans/route.ts'];
  const imports = (s) => /import\s*\{[^}]*\bSCAN_SCOPE_KINDS\b[^}]*\}\s*from\s*'[^']*standard\/schema-vocab(?:\.ts)?'/.test(s);
  const bad = files.filter((f) => { const s = stripComments(read(f)); return !imports(s) || !/\bKINDS\b[^;\n]*=[^;\n]*\bSCAN_SCOPE_KINDS\b/.test(s); });
  const kinds = wire.$defs.scanScope.properties.kind.enum;
  check(`scope: scan-sim.ts and scans/route.ts build KINDS from the generated SCAN_SCOPE_KINDS (scanScope.kind, ${kinds.length} values)`,
    !V.__error && same(V.SCAN_SCOPE_KINDS, kinds) && kinds.length === 6 && !bad.length, V.__error ?? (bad.length ? 'no import / KINDS not from it: ' + bad.join(', ') : 'SCAN_SCOPE_KINDS differs from the schema'));
}

// 5. manifest-check and jobs: built from the generated lens ids, manifest keys and proposal id pattern
{
  const ids = lens.$defs.builtinLensId.enum, keys = Object.keys(lens.properties);
  const src = stripComments(read('packages/core/src/scan/manifest-check.ts'));
  const setOf = (s) => (s instanceof Set ? [...s].sort() : null);
  const problems = [];
  if (V.__error || M.__error || J.__error) problems.push(V.__error ?? M.__error ?? J.__error);
  else {
    if (!same(V.BUILTIN_LENS_IDS, ids) || ids.length !== 7) problems.push('BUILTIN_LENS_IDS is not builtinLensId');
    if (!same(V.LENS_MANIFEST_KEYS, keys) || keys.length !== 11) problems.push('LENS_MANIFEST_KEYS is not the root property keys');
    if (!same(setOf(M.BUILTIN_IDS), [...ids].sort()) || !/\bBUILTIN_IDS\b[^;\n]*=\s*new Set(?:<[^>]*>)?\(BUILTIN_LENS_IDS\)/.test(src)) problems.push('BUILTIN_IDS is not new Set(BUILTIN_LENS_IDS)');
    if (!same(setOf(M.TOP), [...keys].sort()) || !/\bTOP\b[^;\n]*=\s*new Set(?:<[^>]*>)?\(LENS_MANIFEST_KEYS\)/.test(src)) problems.push('TOP is not new Set(LENS_MANIFEST_KEYS)');
    if (!(V.PROPOSAL_ID_PATTERN instanceof RegExp) || V.PROPOSAL_ID_PATTERN.source !== wire.$defs.proposalId.pattern) problems.push('PROPOSAL_ID_PATTERN is not proposalId.pattern');
    if (J.SAFE_ID !== V.PROPOSAL_ID_PATTERN) problems.push('jobs.ts SAFE_ID is not the generated PROPOSAL_ID_PATTERN');
  }
  check('manifest-check.ts BUILTIN_IDS (7) and TOP (11), and jobs.ts SAFE_ID, are built from the generated BUILTIN_LENS_IDS, LENS_MANIFEST_KEYS and PROPOSAL_ID_PATTERN', !problems.length, problems.join('; '));
}

// GUARD: SAFE_ID's behaviour (pinned before the change, must hold after it)
{
  const re = J.SAFE_ID;
  const got = re instanceof RegExp ? [re.test('k-des-3'), re.test('K-DES-3'), re.test('-x'), re.test('a'.repeat(82)), re.test('a'.repeat(81))] : [];
  check("GUARD: SAFE_ID accepts 'k-des-3', 'K-DES-3' and 81 characters, refuses '-x' and 82 characters", same(got, [true, true, false, false, true]), JSON.stringify(got));
}

// 6. literals: no hand copy of a schema enum is left in core, and the scan bites
{
  const enums = [];
  const walk = (node, file, at) => {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node.enum) && node.enum.length >= 3 && node.enum.every((v) => typeof v === 'string')) enums.push({ name: `${file.replace('.schema.json', '')} ${at.filter((k) => k !== '$defs' && k !== 'properties').join('.')}`, set: [...new Set(node.enum)].sort() });
    for (const [k, v] of Object.entries(node)) if (k !== 'enum') walk(v, file, [...at, k]);
  };
  for (const f of fs.readdirSync(path.join(ROOT, 'packages/schema/schema')).filter((f) => f.endsWith('.schema.json'))) walk(schemaOf(f), f, []);
  const STR = String.raw`(?:'[^'\n]*'|"[^"\n]*")`, LIST = new RegExp(String.raw`\[\s*${STR}(?:\s*,\s*${STR}){2,}\s*,?\s*\]`, 'g');
  const scan = (text) => [...stripComments(text).matchAll(LIST)].flatMap((m) => {
    const set = [...new Set([...m[0].matchAll(/'([^'\n]*)'|"([^"\n]*)"/g)].map((x) => x[1] ?? x[2]))].sort();
    return enums.filter((e) => same(e.set, set)).map((e) => e.name);
  });
  const walkTs = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walkTs(path.join(d, e.name)) : e.name.endsWith('.ts') || e.name.endsWith('.tsx') ? [path.join(d, e.name)] : []));
  const files = walkTs(path.join(ROOT, 'packages/core/src')).filter((f) => rel(f) !== VOCAB);
  const all = files.flatMap((f) => scan(fs.readFileSync(f, 'utf8')).map((n) => `${rel(f)}: ${n}`));
  // Known copies outside this change's files, allowed by name until they import the generated value; an entry that
  // stops being a hit fails below, so the list cannot outlive its fix.
  const KNOWN = ['packages/core/src/standard/types.ts: lens-manifest-1 featureBoundField',
    'packages/core/src/standard/present.ts: lens-manifest-1 field.allOf.2.if.type', 'packages/core/src/standard/present.ts: lens-manifest-1 field.allOf.3.then.type'];
  const hits = all.filter((h) => !KNOWN.includes(h)), fixed = KNOWN.filter((k) => !all.includes(k));
  const control = scan(`const K = new Set(['feature','bay','room','wing','all','selection']);\n// const C = ['good', 'watch', 'bad'];`);
  check(`literals: no array or Set literal in packages/core/src (${files.length} files, ${enums.length} schema enums of >= 3) is a hand copy of a schema enum (${KNOWN.length} known copies allowed by name)`, enums.length >= 5 && files.length >= 50 && !hits.length, hits.join('; '));
  check('literals: every allowed known copy is still one', !fixed.length, 'fixed, now delete from KNOWN: ' + fixed.join('; '));
  check('literals control: a seeded Set literal of the six scope kinds is 1 hit naming scanScope.kind (a commented-out copy is not)', control.length === 1 && control[0] === 'scan-wire-1 scanScope.kind', JSON.stringify(control));
}

// 7. scrapers: identity replaced the source-text matchers
{
  const src = read('packages/schema/generate.mjs');
  const left = ['constOf(', 'reOf(', 'BUILTIN_SET_RE'].filter((t) => src.includes(t));
  check('scrapers: generate.mjs contains no constOf(, reOf( or BUILTIN_SET_RE (the source-text matchers are replaced by identity)', !left.length, 'still there: ' + left.join(', '));
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);
